# Get the long descriptions for each command precisely
for f in /tmp/skeema_help/help_add-environment.txt /tmp/skeema_help/help_init.txt /tmp/skeema_help/help_format.txt /tmp/skeema_help/help_pull.txt /tmp/skeema_help/help_lint.txt /tmp/skeema_help/help_diff.txt /tmp/skeema_help/help_push.txt /tmp/skeema_help/help_version.txt /tmp/skeema_help/help_help.txt; do
  echo "===== $f ====="
  # Print from the line after "Usage:" and blank line, up to next blank line or "Options:" section
  awk '
    /^Usage:/ { found_usage=1; next }
    found_usage && /^$/ && !in_desc { in_desc=1; next }
    found_usage && /^[A-Z].* Options:/ { exit }
    in_desc { print }
  ' "$f"
done

