cat > /workspace/help.go <<'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// optionSpec returns the left-hand "option specification" text for the given
// option, e.g. "  -o, --connect-options value", "      --debug",
// "      --[skip-]my-cnf", "  -?, --help[=value]".
func optionSpec(o Option) string {
	var b strings.Builder
	if o.Short != 0 {
		b.WriteString(fmt.Sprintf("  -%c, ", o.Short))
	} else {
		b.WriteString("      ")
	}

	switch o.Type {
	case OptSkipBool:
		b.WriteString("--[skip-]")
		b.WriteString(o.Long)
	case OptOptVal:
		b.WriteString("--")
		b.WriteString(o.Long)
		b.WriteString("[=value]")
	case OptValue:
		b.WriteString("--")
		b.WriteString(o.Long)
		b.WriteString(" value")
	default: // OptBool
		b.WriteString("--")
		b.WriteString(o.Long)
	}
	return b.String()
}

// optionDescription returns the description, possibly with a trailing
// " (default "xxx")" appended.
func optionDescription(o Option) string {
	desc := o.Description
	if o.HasDefault {
		desc = desc + fmt.Sprintf(" (default %q)", o.Default)
	}
	return desc
}

// commandListEntry returns e.g. `      add-environment  Add a new named environment to an existing host directory`
// padded so short descriptions align.
func commandListLine(c *Command, nameWidth int) string {
	// 6 spaces before name
	return fmt.Sprintf("      %-*s  %s", nameWidth, c.Name, c.ShortDesc)
}

// renderHelp produces the help output for a command.
func renderHelp(c *Command) string {
	var b strings.Builder
	b.WriteString("\n")
	b.WriteString("Usage:  skeema ")
	b.WriteString(c.Usage)
	b.WriteString("\n\n")
	if c.LongDesc != "" {
		b.WriteString(c.LongDesc)
		b.WriteString("\n\n")
	}
	if c.Suite {
		// Include command listing
		b.WriteString("Commands:\n")
		// Compute width of longest command name
		maxLen := 0
		for _, cc := range allCommands {
			if len(cc.Name) > maxLen {
				maxLen = len(cc.Name)
			}
		}
		for _, cc := range allCommands {
			b.WriteString(commandListLine(cc, maxLen))
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	// Compute max option spec width across all option groups for this command
	maxOptWidth := 0
	for _, g := range c.OptionGroups {
		for _, o := range g.Options {
			w := len(optionSpec(o))
			if w > maxOptWidth {
				maxOptWidth = w
			}
		}
	}
	descCol := maxOptWidth + 2

	for i, g := range c.OptionGroups {
		b.WriteString(g.Title)
		b.WriteString("\n")
		for _, o := range g.Options {
			spec := optionSpec(o)
			// pad spec with spaces up to descCol
			b.WriteString(spec)
			b.WriteString(strings.Repeat(" ", descCol-len(spec)))
			b.WriteString(optionDescription(o))
			b.WriteString("\n")
		}
		if i < len(c.OptionGroups)-1 {
			b.WriteString("\n")
		}
	}
	b.WriteString("\n")
	// Closing doc line
	if c.Suite {
		b.WriteString("Complete documentation for this command suite is available online:\n")
	} else {
		b.WriteString("Complete documentation for this command is available online:\n")
	}
	b.WriteString(c.DocURL)
	b.WriteString("\n\n")
	return b.String()
}
GOEOF
