cat > /workspace/main.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

const (
	exitSuccess     = 0
	exitDifferences = 1
	exitError       = 2
	exitBadConfig   = 78 // EX_CONFIG
)

const versionString = "skeema version 1.13.2-community, commit a65240e, released 2026-04-17T20:00:03Z"

var (
	debug bool
)

// logMsg prints a log line of the form "YYYY-MM-DD HH:MM:SS [LEVEL] message"
// to stderr (matching observed behaviour of the reference binary).
func logMsg(level, msg string) {
	now := time.Now().Format("2006-01-02 15:04:05")
	// Two spaces after [LEVEL] for DEBUG/WARN/INFO (which are 4-5 chars), one
	// space for ERROR (5 chars).  The reference pads them using %-5s.
	pad := ""
	if len(level) < 5 {
		pad = strings.Repeat(" ", 5-len(level))
	}
	fmt.Fprintf(os.Stderr, "%s [%s]%s %s\n", now, level, pad, msg)
}

func logError(msg string)   { logMsg("ERROR", msg) }
func logWarn(msg string)    { logMsg("WARN", msg) }
func logInfo(msg string)    { logMsg("INFO", msg) }
func logDebug(msg string)   { logMsg("DEBUG", msg) }

// exitWithCode prints the debug "Exit code N" line if debug is enabled and exits.
func exitWithCode(code int) {
	if debug {
		label := ""
		if code == exitSuccess {
			label = " (SUCCESS)"
		}
		logDebug(fmt.Sprintf("Exit code %d%s", code, label))
	}
	os.Exit(code)
}

// parseContext tracks state while parsing command-line arguments.
type parseContext struct {
	cmd     *Command
	options map[string]string
	bools   map[string]bool
	posArgs []string
	// whenever --help / -? is seen, helpTarget is set (may be "" meaning current cmd)
	helpRequested bool
	helpTarget    string
	versionFlag   bool
}

// findOption locates an option (in global + command option groups) by its long name.
// Returns the option and whether it was found.
func (pc *parseContext) findOption(long string) (Option, bool) {
	// Also check --skip-<name> for OptSkipBool
	if strings.HasPrefix(long, "skip-") {
		name := strings.TrimPrefix(long, "skip-")
		if o, ok := pc.findOption(name); ok && o.Type == OptSkipBool {
			return o, true
		}
	}
	groups := pc.cmd.OptionGroups
	for _, g := range groups {
		for _, o := range g.Options {
			if o.Long == long {
				return o, true
			}
		}
	}
	return Option{}, false
}

// findShortOption locates an option by its short character.
func (pc *parseContext) findShortOption(short rune) (Option, bool) {
	for _, g := range pc.cmd.OptionGroups {
		for _, o := range g.Options {
			if o.Short == short {
				return o, true
			}
		}
	}
	return Option{}, false
}

// parseArgs parses the argument list given the command's option set. It
// returns an error string on parse failure.
func parseArgs(cmd *Command, args []string) (*parseContext, string) {
	pc := &parseContext{
		cmd:     cmd,
		options: map[string]string{},
		bools:   map[string]bool{},
	}

	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if a == "--" {
			// All remaining are positional
			pc.posArgs = append(pc.posArgs, args[i:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			body := a[2:]
			if body == "" {
				return nil, `Unknown option ""`
			}
			name, val, hasVal := strings.Cut(body, "=")
			o, ok := pc.findOption(name)
			if !ok {
				return nil, fmt.Sprintf("Unknown option %q", name)
			}
			isSkip := strings.HasPrefix(name, "skip-") && o.Type == OptSkipBool
			switch o.Type {
			case OptBool:
				if hasVal {
					// Bool flags don't accept value explicitly but accept --flag=true/false perhaps.
					// For the purposes of this implementation we accept anything truthy.
					pc.bools[o.Long] = val != "false" && val != "0"
				} else {
					pc.bools[o.Long] = true
				}
			case OptSkipBool:
				v := true
				if isSkip {
					v = false
				}
				if hasVal {
					if val == "false" || val == "0" {
						v = !v // negate
					}
				}
				pc.bools[o.Long] = v
			case OptValue:
				if !hasVal {
					if i >= len(args) {
						return nil, fmt.Sprintf("Missing required value for option %s", o.Long)
					}
					val = args[i]
					i++
				}
				pc.options[o.Long] = val
			case OptOptVal:
				if hasVal {
					pc.options[o.Long] = val
				} else {
					pc.options[o.Long] = ""
				}
				// Track help/version explicitly
				if o.Long == "help" {
					pc.helpRequested = true
					pc.helpTarget = pc.options["help"]
				}
				if o.Long == "version" {
					pc.versionFlag = true
				}
			}
			if o.Long == "debug" {
				debug = pc.bools["debug"]
			}
			if o.Long == "version" {
				pc.versionFlag = true
			}
			if o.Long == "help" {
				pc.helpRequested = true
			}
			if o.Long == "my-cnf" && pc.bools["my-cnf"] == false && isSkip {
				// --skip-my-cnf triggers the deprecation warning
				logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
			}
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// Short option(s). Skeema uses single-char short options.
			body := a[1:]
			// Iterate runes - but skeema actually uses single short with possible value
			r := rune(body[0])
			rest := body[1:]
			o, ok := pc.findShortOption(r)
			if !ok {
				return nil, fmt.Sprintf("Unknown option %q", string(r))
			}
			switch o.Type {
			case OptBool:
				pc.bools[o.Long] = true
				// remaining chars = more short options? For simplicity treat rest as additional flags
				for _, rr := range rest {
					o2, ok := pc.findShortOption(rr)
					if !ok {
