package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

const (
	exitSuccess     = 0
	exitDifferences = 1
	exitError       = 2
	exitBadConfig   = 78 // EX_CONFIG
)

const versionString = "skeema version 1.13.2-community, commit a65240e, released 2026-04-17T20:00:03Z"

var debug bool

// logMsg prints a log line of the form "YYYY-MM-DD HH:MM:SS [LEVEL] message".
// The [LEVEL] field is left-padded to match the widest level name (ERROR/DEBUG).
func logMsg(level, msg string) {
	now := time.Now().Format("2006-01-02 15:04:05")
	pad := ""
	if len(level) < 5 {
		pad = strings.Repeat(" ", 5-len(level))
	}
	fmt.Fprintf(os.Stderr, "%s [%s]%s %s\n", now, level, pad, msg)
}

func logError(msg string) { logMsg("ERROR", msg) }
func logWarn(msg string)  { logMsg("WARN", msg) }
func logInfo(msg string)  { logMsg("INFO", msg) }
func logDebug(msg string) { logMsg("DEBUG", msg) }

func exitWithCode(code int) {
	if debug {
		label := ""
		if code == exitSuccess {
			label = " (SUCCESS)"
		}
		logDebug(fmt.Sprintf("Exit code %d%s", code, label))
	}
	os.Exit(code)
}

type parseState struct {
	cmd           *Command
	options       map[string]string
	bools         map[string]bool
	posArgs       []string
	helpRequested bool
	helpTarget    string
	versionFlag   bool
}

func newParseState(cmd *Command) *parseState {
	return &parseState{
		cmd:     cmd,
		options: map[string]string{},
		bools:   map[string]bool{},
	}
}

// findOpt searches the command's option groups (which include globalOptions)
// for an option with the given long name. Handles --skip- prefix for
// OptSkipBool options.
func findOpt(cmd *Command, long string) (Option, bool, bool) {
	isSkip := false
	name := long
	if strings.HasPrefix(long, "skip-") {
		inner := strings.TrimPrefix(long, "skip-")
		for _, g := range cmd.OptionGroups {
			for _, o := range g.Options {
				if o.Long == inner && o.Type == OptSkipBool {
					return o, true, true
				}
			}
		}
	}
	for _, g := range cmd.OptionGroups {
		for _, o := range g.Options {
			if o.Long == name {
				return o, true, isSkip
			}
		}
	}
	return Option{}, false, false
}

func findShortOpt(cmd *Command, r rune) (Option, bool) {
	for _, g := range cmd.OptionGroups {
		for _, o := range g.Options {
			if o.Short == r {
				return o, true
			}
		}
	}
	return Option{}, false
}

// parseArgs parses the argument list for a specific command.  If the command
// is nil, the suite (global) options are used; tokens that cannot be
// interpreted as options are treated as the command name and parsing stops,
// returning the remaining args for later command-specific parsing.
func parseArgs(cmd *Command, args []string) (*parseState, []string, string) {
	ps := newParseState(cmd)
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if a == "--" {
			ps.posArgs = append(ps.posArgs, args[i:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			body := a[2:]
			if body == "" {
				return nil, nil, `Unknown option ""`
			}
			name, val, hasVal := strings.Cut(body, "=")
			o, ok, isSkip := findOpt(cmd, name)
			if !ok {
				return nil, nil, fmt.Sprintf("Unknown option %q", name)
			}
			switch o.Type {
			case OptBool:
				if hasVal {
					ps.bools[o.Long] = val != "false" && val != "0"
				} else {
					ps.bools[o.Long] = true
				}
			case OptSkipBool:
				v := true
				if isSkip {
					v = false
				}
				if hasVal {
					if val == "false" || val == "0" {
						v = !v
					}
				}
				ps.bools[o.Long] = v
			case OptValue:
				if !hasVal {
					if i >= len(args) {
						return nil, nil, fmt.Sprintf("Missing required value for option %s", o.Long)
					}
					val = args[i]
					i++
				}
				ps.options[o.Long] = val
			case OptOptVal:
				if hasVal {
					ps.options[o.Long] = val
				} else {
					ps.options[o.Long] = ""
				}
			}
			if o.Long == "help" {
				ps.helpRequested = true
				ps.helpTarget = ps.options["help"]
			}
			if o.Long == "version" && o.Type == OptBool {
				ps.versionFlag = true
			}
			if o.Long == "debug" {
				if ps.bools["debug"] {
					debug = true
				}
			}
			if o.Long == "my-cnf" && isSkip {
				logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
			}
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			body := a[1:]
			r := rune(body[0])
			rest := body[1:]
			o, ok := findShortOpt(cmd, r)
			if !ok {
				return nil, nil, fmt.Sprintf("Unknown option %q", string(r))
			}
			switch o.Type {
			case OptBool:
				ps.bools[o.Long] = true
				if o.Long == "debug" {
					debug = true
				}
				// additional packed short flags (treat remaining as flags)
				for _, rr := range rest {
					o2, ok := findShortOpt(cmd, rr)
					if !ok {
						return nil, nil, fmt.Sprintf("Unknown option %q", string(rr))
					}
					if o2.Type != OptBool {
						return nil, nil, fmt.Sprintf("Missing required value for option %s", o2.Long)
					}
					ps.bools[o2.Long] = true
					if o2.Long == "debug" {
						debug = true
					}
				}
			case OptSkipBool:
				ps.bools[o.Long] = true
			case OptValue:
				val := rest
				if val == "" {
					if i >= len(args) {
						return nil, nil, fmt.Sprintf("Missing required value for option %s", o.Long)
					}
					val = args[i]
					i++
				}
				ps.options[o.Long] = val
			case OptOptVal:
				if rest != "" {
					ps.options[o.Long] = rest
				} else {
					ps.options[o.Long] = ""
				}
				if o.Long == "help" {
					ps.helpRequested = true
					ps.helpTarget = ps.options["help"]
				}
			}
			continue
		}
		// First non-option arg: rest are positional (for command parse) or the command name (for suite parse)
		remaining := append([]string{a}, args[i:]...)
		return ps, remaining, ""
	}
	return ps, nil, ""
}

