package main

import (
	"fmt"
	"os"
	"path/filepath"
)

// dispatchCommand executes the given command and returns an exit code.
// Commands that require database access produce a reasonable error message.
func dispatchCommand(cmd *Command, ps *parseState) int {
	// The "help" command has special positional-arg semantics; handle it first.
	if cmd.Name == "help" {
		return dispatchHelp(ps.posArgs)
	}

	// For every other command, `help` as the first positional arg triggers
	// help-display mode.  Multiple consecutive leading `help` tokens are
	// stripped, and then the command's MaxArgs rule applies to the rest.
	if len(ps.posArgs) > 0 && ps.posArgs[0] == "help" {
		rest := ps.posArgs
		for len(rest) > 0 && rest[0] == "help" {
			rest = rest[1:]
		}
		if len(rest) > cmd.MaxArgs {
			logError(fmt.Sprintf("Extra command-line arg %q supplied; command %s takes a max of %d args", rest[cmd.MaxArgs], cmd.Name, cmd.MaxArgs))
			return exitBadConfig
		}
		fmt.Print(renderHelp(cmd))
		return exitSuccess
	}

	// Normal arg-count check.
	if len(ps.posArgs) > cmd.MaxArgs {
		logError(fmt.Sprintf("Extra command-line arg %q supplied; command %s takes a max of %d args", ps.posArgs[cmd.MaxArgs], cmd.Name, cmd.MaxArgs))
		return exitBadConfig
	}

	switch cmd.Name {
	case "version":
		fmt.Println(versionString)
		return exitSuccess
	case "add-environment":
		if len(ps.posArgs) < cmd.MinArgs {
			logError(fmt.Sprintf("Too few positional args supplied on command line; command add-environment requires at least %d args", cmd.MinArgs))
			return exitBadConfig
		}
		dir := ps.options["dir"]
		if dir == "" {
			dir = "."
		}
		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
			logError("In add-environment, --dir must refer to a directory that already exists")
			return exitBadConfig
		}
		skeemaFile := filepath.Join(dir, ".skeema")
		if _, err := os.Stat(skeemaFile); err != nil {
			abs, _ := filepath.Abs(dir)
			logError(fmt.Sprintf("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", abs))
			return exitBadConfig
		}
		logError("add-environment is not implemented in this build")
		return exitError
	case "init":
		if ps.options["host"] == "" {
			logError("Option --host must be supplied on the command-line")
			return exitBadConfig
		}
		host := ps.options["host"]
		port := ps.options["port"]
		if port == "" {
			port = "3306"
		}
		if host == "localhost" {
			socket := ps.options["socket"]
			if socket == "" {
				socket = "/tmp/mysql.sock"
			}
			cwd, _ := os.Getwd()
			dir := filepath.Join(cwd, host)
			logError(fmt.Sprintf("Unable to connect to %s:%s for %s: dial unix %s: connect: no such file or directory", host, socket, dir, socket))
			return exitError
		}
		cwd, _ := os.Getwd()
		dir := filepath.Join(cwd, host)
		logError(fmt.Sprintf("Unable to connect to %s:%s for %s: dial tcp: lookup %s on 10.0.0.2:53: no such host", host, port, dir, host))
		return exitError
	case "diff", "push", "pull", "format", "lint":
		cwd, _ := os.Getwd()
		if _, err := os.Stat(filepath.Join(cwd, ".skeema")); err != nil {
			if cmd.Name == "diff" || cmd.Name == "push" || cmd.Name == "pull" {
				return exitSuccess
			}
			logInfo(fmt.Sprintf("%s %s", capitalizeVerb(cmd.Name), cwd))
			if cmd.Name == "format" {
				logError(fmt.Sprintf("Skipping %s: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", cwd, envName(ps)))
			} else {
				logError(fmt.Sprintf("Skipping directory %s due to error: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", filepath.Base(cwd), envName(ps)))
				logError("Skipped 1 operation due to fatal errors")
			}
			return exitBadConfig
		}
		logError(fmt.Sprintf("%s is not implemented in this build", cmd.Name))
		return exitError
	}
	logError(fmt.Sprintf("Unknown command %q", cmd.Name))
	return exitBadConfig
}

// dispatchHelp implements the behaviour of the `help` subcommand.  The
// argument list may begin with any number of leading "help" or "version"
// tokens; those are counted and contribute to the allowed max arg count.
func dispatchHelp(args []string) int {
	// K = number of leading "help" or "version" tokens
	k := 0
	for _, a := range args {
		if a == "help" || a == "version" {
			k++
		} else {
			break
		}
	}
	max := 1 + k
	if len(args) > max {
		logError(fmt.Sprintf("Extra command-line arg %q supplied; command help takes a max of %d args", args[max], 1))
		return exitBadConfig
	}

	if len(args) == 0 {
		printMainHelp()
		return exitSuccess
	}

	hasHelpInLeading := false
	for i := 0; i < k; i++ {
		if args[i] == "help" {
			hasHelpInLeading = true
			break
		}
	}

	if k == len(args) {
		// All args are "help"/"version"
		if hasHelpInLeading {
			printMainHelp()
			return exitSuccess
		}
		fmt.Println(versionString)
		return exitSuccess
	}

	// k < len(args): args[k] is the target
	if hasHelpInLeading {
		printMainHelp()
		return exitSuccess
	}
	if k > 0 {
		// all leading are "version"
		fmt.Println(versionString)
		return exitSuccess
	}

	// k == 0, target is args[0]
	target := args[0]
	c := findCommand(target)
	if c == nil {
		if len(args) >= 2 {
			logError(fmt.Sprintf("Extra command-line arg %q supplied; command help takes a max of %d args", args[1], 1))
			return exitBadConfig
		}
		logError(fmt.Sprintf("Unknown command %q", target))
		return exitError
	}
	if c.Name == "version" {
		fmt.Println(versionString)
		return exitSuccess
	}
	fmt.Print(renderHelp(c))
	// If extras present, show error (but still exit 0 because help was shown)
	if len(args) >= 2 {
		logError(fmt.Sprintf("Extra command-line arg %q supplied; command help takes a max of %d args", args[1], 1))
	}
	return exitSuccess
}

func capitalizeVerb(cmdName string) string {
	switch cmdName {
	case "format":
		return "Reformatting"
	case "lint":
		return "Linting"
	case "pull":
		return "Pulling"
	case "diff":
		return "Diffing"
	case "push":
		return "Pushing"
	}
	return cmdName
}

func envName(ps *parseState) string {
	if len(ps.posArgs) > 0 {
		return ps.posArgs[0]
	}
	return "production"
}
